const items = $input.all();

let justificativas = [];
let edits = [];

// Separar os dados
items.forEach((item, i) => {
  if (item.json.justificativa) {
    justificativas.push({
      index: i,
      justificativa: item.json.justificativa
    });
  }

  if (item.json.edited) {
    edits.push({
      index: i,
      edited: item.json.edited
    });
  }
});

// ⚠️ Ajuste aqui se quiser casar por ordem real
const resultado = [];

for (let i = 0; i < justificativas.length; i++) {
  resultado.push({
    json: {
      justificativa: justificativas[i]?.justificativa || null,
      edited: edits[i]?.edited || null
    }
  });
}

return resultado;
